class TestRecordSubjects(unittest.TestCase):
    def test_public_fixture_shape(self):
        payload = {
            "records": [
                {"table": "orders", "id": "o1", "tenant": "a", "subject": "t", "time": 1},
                {"table": "history", "id": "v1", "tenant": "a", "subject": "s", "time": 7},
                {"table": "events", "id": "e1", "tenant": "b", "subject": "u", "time": 7},
            ]
        }
        out = compute(payload)
        self.assertEqual(out, [
            ["orders", "o1", 1, ["a", "t"]],
            ["history", "v1", 7, ["a", "s"]],
            ["events", "e1", 7, ["b", "u"]],
        ])

    def test_preserves_order_and_tenant_scope(self):
        payload = {
            "records": [
                {"table": "t1", "id": "x", "tenant": "z", "subject": "s", "time": 0},
                {"table": "t2", "id": "y", "tenant": "z", "subject": "s", "time": 5},
            ]
        }
        out = compute(payload)
        self.assertEqual(out[0][3], ["z", "s"])
        self.assertEqual(out[1][3], ["z", "s"])
        self.assertEqual([r[0] for r in out], ["t1", "t2"])


if __name__ == "__main__":
    unittest.main()

